package com.ruoyi.paismart.application.intelligence;
import com.aliyun.ocr_api20210707.Client;
import com.aliyun.ocr_api20210707.models.RecognizeAllTextRequest;
import com.aliyun.teaopenapi.models.Config;
import com.aliyun.teautil.models.RuntimeOptions;
import com.aliyun.teautil.Common;
import com.ruoyi.paismart.application.jobs.JobService;
import com.ruoyi.paismart.application.documents.DocumentService;
import com.ruoyi.paismart.infrastructure.Jsons;
import com.ruoyi.paismart.infrastructure.intelligence.*;
import org.springframework.stereotype.Service;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionTemplate;
import java.io.*;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.time.LocalDateTime;
import java.util.*;

/** 阿里RecognizeAllText保留；短期作业令牌限定文档版本、租约和调用页数。 */
@Service
@ConditionalOnProperty(name="paismart.enabled",havingValue="true")
public class OcrService {
    private final JdbcTemplate db;private final TransactionTemplate tx;private final JobService jobs;private final DocumentService docs;private final IntelligenceSettings settings;
    public OcrService(@Qualifier("paismartJdbc")JdbcTemplate db,@Qualifier("paismartTransactionTemplate")TransactionTemplate tx,JobService jobs,DocumentService docs,IntelligenceSettings settings){this.db=db;this.tx=tx;this.jobs=jobs;this.docs=docs;this.settings=settings;}
    private String hash(String text){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
    public String callback(JobService.Job job){if(!settings.enabled("ocr.aliyun-enabled"))return "";jobs.requireLease(job.id(),job.leaseToken());String base=settings.text("parse.ocr-callback-base","");URI uri=URI.create(base);if(uri.getHost()==null||!Set.of("127.0.0.1","localhost","::1").contains(uri.getHost())||!Set.of("http","https").contains(uri.getScheme())||uri.getRawQuery()!=null||uri.getUserInfo()!=null)throw new IllegalArgumentException("OCR回调必须为批准的本机中心地址");var doc=docs.getForProcessing(job.documentId());String token=Values.id()+Values.id();db.update("INSERT INTO ps_ocr_ticket(token_hash,job_id,document_id,content_version,lease_token,max_uses,expires_at,created_at) VALUES(?,?,?,?,?,?,?,?)",hash(token),job.id(),doc.id(),doc.contentVersion(),job.leaseToken(),settings.number("parse.max-pages",1000),LocalDateTime.now().plusSeconds(300),LocalDateTime.now());return base.replaceAll("/+$","")+"/paismart/internal/ocr/liteparse?token="+token;}
    private record OcrCall(String id,JobService.Job job,Integer version,String cached){}
    private void image(byte[] bytes){if(bytes==null||bytes.length<8||bytes.length>10*1024*1024)throw new IllegalArgumentException("OCR图片预算无效");boolean jpeg=bytes[0]==(byte)0xff&&bytes[1]==(byte)0xd8,png=bytes[0]==(byte)0x89&&bytes[1]=='P'&&bytes[2]=='N'&&bytes[3]=='G';if(!jpeg&&!png)throw new IllegalArgumentException("OCR只接受受限PNG/JPEG页图");try(var input=new javax.imageio.stream.MemoryCacheImageInputStream(new ByteArrayInputStream(bytes))){var readers=javax.imageio.ImageIO.getImageReaders(input);if(!readers.hasNext())throw new IllegalArgumentException("OCR图片无法识别");var reader=readers.next();try{reader.setInput(input,true,true);int width=reader.getWidth(0),height=reader.getHeight(0);if(width<1||height<1||width>20000||height>20000||(long)width*height>40000000)throw new IllegalArgumentException("OCR页图像素超过预算");}finally{reader.dispose();}}catch(IOException damaged){throw new IllegalArgumentException("OCR图片结构无效");}}
    private String imageHash(byte[] bytes){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
    private Map<String,Object> credentials(){if(!settings.enabled("ocr.aliyun-enabled"))throw new IllegalStateException("云OCR未启用");settings.requireExternal();Map<String,Object> key=Jsons.map(settings.modelSecret(settings.text("ocr.secret-ref","ai.paismart.aliyun.ocr"),"OCR","aliyun"));Values.required(key,"accessKeyId",200);Values.required(key,"accessKeySecret",200);return key;}
    private OcrCall begin(long user,String operation,JobService.Job job,Integer version,byte[] bytes){String fingerprint=imageHash(bytes);List<Map<String,Object>> old=db.queryForList("SELECT * FROM ps_ocr_call WHERE user_id=? AND operation_id=? FOR UPDATE",user,operation);if(!old.isEmpty()){var row=old.get(0);if(!fingerprint.equals(row.get("image_hash")))throw new IllegalStateException("同一OCR请求的页图内容不一致");if(!"COMPLETED".equals(row.get("state")))throw new IllegalStateException("OCR远端结果待核对，禁止重复请求；核对后新建明确的处理请求");return new OcrCall(Values.text(row.get("id")),job,version,Values.text(row.get("response_json")));}String id=Values.id();db.update("INSERT INTO ps_ocr_call(id,user_id,operation_id,job_id,document_id,content_version,image_hash,image_bytes,state,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,'STARTED',?,?)",id,user,operation,job==null?null:job.id(),job==null?null:job.documentId(),version,fingerprint,bytes.length,LocalDateTime.now(),LocalDateTime.now());return new OcrCall(id,job,version,null);}
    private void guard(OcrCall call){if(call.job()==null)return;jobs.requireLease(call.job().id(),call.job().leaseToken());var doc=docs.getForProcessing(call.job().documentId());if(doc.deletedAt()!=null||doc.contentVersion()!=call.version())throw new IllegalStateException("OCR文档版本已失效");}
    public Map<String,Object> recognize(String token,byte[] bytes){image(bytes);Map<String,Object> key=credentials();if(token==null||!token.matches("[a-z0-9-]{72}"))throw new IllegalArgumentException("OCR作业令牌无效");OcrCall call=tx.execute(s->{List<Map<String,Object>> rows=db.queryForList("SELECT * FROM ps_ocr_ticket WHERE token_hash=? AND expires_at>CURRENT_TIMESTAMP FOR UPDATE",hash(token));if(rows.size()!=1)throw new IllegalArgumentException("OCR作业令牌失效");Map<String,Object> row=rows.get(0);JobService.Job job=jobs.get(Values.text(row.get("job_id")));jobs.requireLease(job.id(),job.leaseToken());var doc=docs.getForProcessing(job.documentId());if(!Objects.equals(job.leaseToken(),row.get("lease_token"))||doc.contentVersion()!=Values.number(row.get("content_version"),0)||doc.deletedAt()!=null)throw new IllegalStateException("OCR作业版本或租约失效");String operation="page:"+job.id()+":"+doc.contentVersion()+":"+imageHash(bytes);OcrCall result=begin(job.userId(),operation,job,doc.contentVersion(),bytes);if(result.cached()==null){if(Values.number(row.get("used_count"),0)>=Values.number(row.get("max_uses"),0))throw new IllegalStateException("OCR作业页数达到预算");db.update("UPDATE ps_ocr_ticket SET used_count=used_count+1 WHERE token_hash=?",hash(token));}return result;});return perform(call,key,bytes);}
    public Map<String,Object> healthRecognize(long user,String requestKey,byte[] bytes){image(bytes);com.ruoyi.paismart.application.billing.QuotaService.key(requestKey,100);Map<String,Object> key=credentials();OcrCall call=tx.execute(s->{db.queryForObject("SELECT user_id FROM sys_user WHERE user_id=? FOR UPDATE",Long.class,user);return begin(user,"health:"+requestKey,null,null,bytes);});Map<String,Object> response=perform(call,key,bytes);return Map.of("state","READY","callId",call.id(),"actualPages",1,"amountState","PROVIDER_BILL_REQUIRED","results",response.get("results"));}
    private Map<String,Object> perform(OcrCall call,Map<String,Object> key,byte[] bytes){guard(call);if(call.cached()!=null)return Jsons.map(call.cached());try{Config config=new Config().setAccessKeyId(Values.text(key.get("accessKeyId"))).setAccessKeySecret(Values.text(key.get("accessKeySecret")));config.endpoint="ocr-api.cn-hangzhou.aliyuncs.com";Client client=new Client(config);RecognizeAllTextRequest request=new RecognizeAllTextRequest().setBody(new ByteArrayInputStream(bytes)).setType("Advanced").setOutputCoordinate("points").setOutputOricoord(true);guard(call);var result=client.recognizeAllTextWithOptions(request,new RuntimeOptions().setConnectTimeout(10000).setReadTimeout(60000));if(result.getBody()==null||!("200".equals(result.getBody().getCode())||result.getBody().getCode()==null))throw new IllegalStateException("OCR供应商返回失败");Map<String,Object> response=adapt(Jsons.map(Common.toJSONString(result.getBody().getData())));Map<String,Object> envelope=Jsons.map(Common.toJSONString(result.getBody()));db.update("UPDATE ps_ocr_call SET state='COMPLETED',actual_pages=1,provider_request_id=?,response_json=?,updated_at=? WHERE id=? AND state='STARTED'",Values.text(envelope.getOrDefault("requestId",envelope.get("RequestId"))),Jsons.write(response),LocalDateTime.now(),call.id());guard(call);return response;}catch(Exception failure){db.update("UPDATE ps_ocr_call SET state='UNCERTAIN',reason=?,updated_at=? WHERE id=? AND state='STARTED'",Values.safeError(failure),LocalDateTime.now(),call.id());throw new IllegalStateException("PROVIDER_UNAVAILABLE:云OCR调用未完成，请按调用编号核对结果",failure);}}
    public List<Map<String,Object>> unresolved(){return db.queryForList("SELECT id,user_id AS userId,job_id AS jobId,document_id AS documentId,content_version AS contentVersion,state,image_bytes AS imageBytes,provider_request_id AS providerRequestId,created_at AS createdAt,reason FROM ps_ocr_call WHERE state IN ('STARTED','UNCERTAIN') ORDER BY created_at LIMIT 500");}
    public void reconcile(String id,int actualPages,String reason){if(actualPages<0||actualPages>1||reason==null||reason.isBlank()||reason.length()>500)throw new IllegalArgumentException("OCR核对必须提供供应商实际计费页数0或1及依据");if(db.update("UPDATE ps_ocr_call SET state='RECONCILED',actual_pages=?,reason=?,updated_at=? WHERE id=? AND state IN ('STARTED','UNCERTAIN')",actualPages,reason,LocalDateTime.now(),id)!=1)throw new IllegalStateException("OCR调用已被核对或不存在");}
    public Map<String,Object> health(){boolean enabled=settings.enabled("ocr.aliyun-enabled");boolean configured=false;try{settings.modelSecret(settings.text("ocr.secret-ref","ai.paismart.aliyun.ocr"),"OCR","aliyun");configured=true;}catch(RuntimeException missing){}return Map.of("enabled",enabled,"configured",configured,"state",enabled&&configured?"CONFIGURED_NOT_TESTED":"DISABLED_OR_MISSING");}
    public static Map<String,Object> adapt(Map<String,Object> data){List<Map<String,Object>> results=new ArrayList<>();for(Object raw:Values.list(data.getOrDefault("SubImages",data.get("subImages")))){Map<String,Object> image=Values.map(raw),info=Values.map(image.getOrDefault("BlockInfo",image.get("blockInfo")));for(Object value:Values.list(info.getOrDefault("BlockDetails",info.get("blockDetails")))){Map<String,Object> block=Values.map(value);String text=Values.text(block.getOrDefault("BlockContent",block.get("blockContent"))).trim();if(text.isEmpty())continue;List<Object> points=Values.list(block.getOrDefault("BlockPoints",block.get("blockPoints")));double minX=Double.POSITIVE_INFINITY,minY=Double.POSITIVE_INFINITY,maxX=0,maxY=0;for(Object point:points){Map<String,Object> p=Values.map(point);double x=number(p.getOrDefault("X",p.get("x"))),y=number(p.getOrDefault("Y",p.get("y")));minX=Math.min(minX,x);minY=Math.min(minY,y);maxX=Math.max(maxX,x);maxY=Math.max(maxY,y);}List<Double> box=points.isEmpty()?List.of(0d,0d,0d,0d):List.of(minX,minY,maxX,maxY);Object rawConfidence=block.getOrDefault("BlockConfidence",block.get("blockConfidence"));double confidence=rawConfidence==null?1:number(rawConfidence);if(confidence>1)confidence/=100;results.add(Map.of("text",text,"bbox",box,"confidence",Math.max(0,Math.min(1,confidence))));}}
        if(results.isEmpty())for(String line:Values.text(data.getOrDefault("Content",data.get("content"))).split("\\R"))if(!line.isBlank())results.add(Map.of("text",line,"bbox",List.of(0d,0d,0d,0d),"confidence",1d));results.sort(Comparator.comparingDouble((Map<String,Object> r)->number(Values.list(r.get("bbox")).get(1))).thenComparingDouble(r->number(Values.list(r.get("bbox")).get(0))));return Map.of("results",results);}
    private static double number(Object value){return value instanceof Number n?n.doubleValue():0;}
}


